struct Reading {
    let sensor: String
    let value: Int
}

func totalsBySensor(_ readings: [Reading]) -> [String: Int] {
    readings.reduce(into: [String: Int]()) { totals, reading in
        totals[reading.sensor, default: 0] += reading.value
    }
}

let readings = [
    Reading(sensor: "wheel", value: 3),
    Reading(sensor: "wheel", value: 2),
    Reading(sensor: "camera", value: 4),
]
print(totalsBySensor(readings))
